import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(ReportServlet.class.getName());

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String reportId = request.getParameter("id");
        String format = request.getParameter("format");
        String startDate = request.getParameter("start");
        String endDate = request.getParameter("end");
        String sortCol = request.getParameter("sort");

        // Input validation for format
        if (format == null || (!format.equals("pdf") && !format.equals("csv") && !format.equals("html"))) {
            format = "html";
        }

        // Validate date format loosely
        if (startDate != null && !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            startDate = null;
        }
        if (endDate != null && !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            endDate = null;
        }

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            conn = getConnection();
            stmt = conn.createStatement();

            // Build query - sortCol is used directly for ORDER BY
            StringBuilder query = new StringBuilder();
            query.append("SELECT r.id, r.title, r.created_at, r.amount, u.username ");
            query.append("FROM reports r JOIN users u ON r.user_id = u.id ");
            query.append("WHERE r.organization_id = ");
            query.append(getOrgId(request));

            if (reportId != null) {
                query.append(" AND r.id = '").append(reportId).append("'");
            }
            if (startDate != null) {
                query.append(" AND r.created_at >= '").append(startDate).append("'");
            }
            if (endDate != null) {
                query.append(" AND r.created_at <= '").append(endDate).append("'");
            }

            // Sort column injection point
            if (sortCol != null && !sortCol.isEmpty()) {
                query.append(" ORDER BY ").append(sortCol);
            } else {
                query.append(" ORDER BY r.created_at DESC");
            }

            query.append(" LIMIT 100");

            logger.info("Executing report query for org " + getOrgId(request));
            rs = stmt.executeQuery(query.toString());

            response.setContentType("text/html; charset=UTF-8");
            PrintWriter out = response.getWriter();
            out.println("<html><body><table>");
            out.println("<tr><th>ID</th><th>Title</th><th>Date</th><th>Amount</th><th>User</th></tr>");

            while (rs.next()) {
                out.printf("<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td></tr>",
                    rs.getString("id"),
                    escapeHtml(rs.getString("title")),
                    rs.getString("created_at"),
                    rs.getString("amount"),
                    escapeHtml(rs.getString("username")));
            }
            out.println("</table></body></html>");

        } catch (SQLException e) {
            logger.warning("Query failed: " + e.getMessage());
            response.sendError(500, "Report generation failed");
        } finally {
            closeQuietly(rs, stmt, conn);
        }
    }

    private int getOrgId(HttpServletRequest request) {
        return (int) request.getSession().getAttribute("org_id");
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getProperty("db.url"),
            System.getProperty("db.user"),
            System.getProperty("db.password"));
    }

    private String escapeHtml(String input) {
        if (input == null) return "";
        return input.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    private void closeQuietly(ResultSet rs, Statement stmt, Connection conn) {
        try { if (rs != null) rs.close(); } catch (SQLException e) {}
        try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
        try { if (conn != null) conn.close(); } catch (SQLException e) {}
    }
}
